   150	    delete linux[id];
   151	    if (id in commonParsed) effective[id] = commonParsed[id];
   152	    else delete effective[id];
   153	  }
   154	}
   155	
   156	doc.version = 1;
   157	doc.platforms = {
   158	  ...platforms,
   159	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
   160	  linux,
   161	  win32: isObject(platforms.win32) ? platforms.win32 : {},
   162	};
   163	writeJson(dest, doc);
   164	// Every key this table claims, written or withdrawn, at its generated value;
   165	// the UI's keep the value last written. Either way a later UI value reads as
   166	// changed, the UI's, rather than as never owned and free to overwrite.
   167	writeJson(sidecar, {
   168	  linux: {
   169	    ...owned,
   170	    ...Object.fromEntries([...theirs].filter((id) => id in prev).map((id) => [id, prev[id]])),
   171	    ...written,
   172	  },
   173	});
     1	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
     2	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
     3	// Super on Linux. See orca.nix.
     4	//
     5	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
     6	//
     7	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
     8	// facade its comment promises) for the definitions, normalisation and the
     9	// conflict check, so a version bump regenerates the table instead of
    10	// silently drifting from it.
    11	const fs = require('fs');
    12	const path = require('path');
    13	
    14	const [shared, chordsFile] = process.argv.slice(2);
    15	const kb = require(path.resolve(shared, 'keybindings.js'));
    16	
    17	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
    18	// "Cmd+Shift+W", Hyprland's modifier and keysym aliases included. An unknown
    19	// modifier fails the build: it may well be a chord Orca uses. A key Orca has
    20	// no name for (Print, Scroll_Lock), or a mouse/switch/media bind, cannot be
    21	// any Orca chord, so it is skipped -- noted in the log, not fatal.
    22	const MODS = {
    23	  SUPER: 'Cmd', WIN: 'Cmd', LOGO: 'Cmd', MOD4: 'Cmd',
    24	  CTRL: 'Ctrl', CONTROL: 'Ctrl',
    25	  ALT: 'Alt', MOD1: 'Alt',
    26	  SHIFT: 'Shift',
    27	};
    28	const KEYS = {
    29	  return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown',
    30	  grave: 'Backquote', Prior: 'PageUp', Next: 'PageDown',
    31	};
    32	const taken = new Set();
    33	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
    34	  const parts = chord.split('+').map((s) => s.trim());
    35	  const key = parts.pop();
    36	  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
    37	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
    38	  if (!mods.every(Boolean)) throw new Error(`unknown modifier in Hyprland bind "${chord}"`);
    39	  // Bare keys too: Orca's few bare chords (F7, Delete) can be Hyprland's.
    40	  const n = kb.normalizeKeybindingWithOptions([...mods, KEYS[key] ?? key].join('+'), {
    41	    allowBareKeybindings: true,
    42	    allowShiftOnlyKeybindings: true,
    43	  });
    44	  if (n.ok) taken.add(n.value);
    45	  else console.error(`Hyprland bind "${chord}" is no Orca chord (${n.error}); skipped`);
    46	}
    47	// A digit-index action's one binding stands for its whole 1-9 family.
    48	const isTaken = (id, binding) =>
    49	  kb.isDigitIndexActionId(id)
    50	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
    51	    : taken.has(binding);
    52	
    53	const overrides = {};
    54	// Actions every one of whose Mac chords Hyprland took: left on Linux defaults.
    55	const fellBack = new Set();
    56	for (const def of kb.KEYBINDING_DEFINITIONS) {
    57	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
    58	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
    59	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
    60	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
    61	    return n.value;
    62	  });
    63	  const free = mac.filter((b) => !isTaken(def.id, b));
    64	  if (free.length < mac.length) {
    65	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
    66	  }
    67	  // Every chord taken: leave the action on its Linux default rather than
    68	  // unbinding it. No macOS binding at all is different -- unbound there, so
    69	  // unbound here ([]). Same as the Linux default: nothing to say.
    70	  if (mac.length > 0 && free.length === 0) {
    71	    fellBack.add(def.id);
    72	    continue;
    73	  }
    74	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
    75	  overrides[def.id] = free;
    76	}
    77	
    78	// A fallback can land on a generated chord the Mac table never had to keep
    79	// apart from it. Orca dispatches some actions across scopes, ahead of the
    80	// conflict check's scope groups -- the workspace digits before the tab
    81	// digits -- so with Super+1..9 Hyprland's, workspace.selectByIndex stays on
    82	// Ctrl+1..9 and the Mac tab.selectByIndex (Ctrl+1..9) would never fire.
    83	// Such an action goes back to its own Linux default too, until none is left.
    84	const identities = (id, bindings) =>
    85	  bindings.flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
    86	for (;;) {
    87	  const held = new Set(
    88	    [...fellBack].flatMap((id) => identities(id, kb.getDefaultBindings(kb.getKeybindingDefinition(id), 'linux'))),
    89	  );
    90	  const shadowed = Object.keys(overrides).filter((id) => identities(id, overrides[id]).some((i) => held.has(i)));
    91	  if (shadowed.length === 0) break;
    92	  for (const id of shadowed) {
    93	    console.error(`${id}: ${overrides[id].join(', ')} is a fallen-back Linux default's`);
    94	    delete overrides[id];
    95	    fellBack.add(id);
    96	  }
    97	}
    98	
    99	// Orca drops every action in a conflicting set at load, with only a line in
   100	// its diagnostics; fail the build instead.
   101	const conflicts = kb.findKeybindingConflicts('linux', overrides);
   102	if (conflicts.length > 0) {
   103	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
   104	}
   105	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
diff --git a/orca.nix b/orca.nix
index 72e5e26b..5fe77a4b 100644
--- a/orca.nix
+++ b/orca.nix
@@ -89,6 +89,66 @@ let
   # Extracted once, shared by the wrapper's extraInstallCommands below;
   # let bindings are recursive, so position in the block does not matter.
   appimageContents = pkgs.appimageTools.extract { inherit pname version src; };
+
+  # Mac-style shortcuts, the same Super-for-Cmd scheme as gtk's mac-bindings
+  # and ghostty's super+c/v in home.nix: Orca's own macOS defaults, with Cmd
+  # spelled out, which Orca binds to Super (event.metaKey) on Linux. Ctrl+C is
+  # SIGINT again, not copy; Ctrl+Tab and Ctrl+PageUp/Down cycle tabs, as on a
+  # Mac.
+  #
+  # Generated from the app's own keybinding definitions at build time
+  # (nix/orca-mac-keybindings.js), so a version bump picks up new actions.
+  # Chords Hyprland binds are skipped and those actions keep their Linux Ctrl
+  # default -- the compositor would eat them, leaving a dead key. On shiori
+  # that is 19 actions, Super+F (find) and Super+P (go to file) among them,
+  # plus Super+B/N/E, the digits, and their Shift forms; so Ctrl+F/P/B/N/E stay
+  # Orca's. And an action whose Mac chord such a fallback would shadow falls
+  # back too: tab.selectByIndex keeps Alt+1..9, since Ctrl+1..9 stays the
+  # workspaces'. The build log lists every one.
+  #
+  # A running Orca reads the file once; after a switch, restart it (or run its
+  # keybindings reload) for the new table to apply.
+  hyprlandChords = let s = config.wayland.windowManager.hyprland.settings; in
+    lib.concatMap
+      (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k})
+      # bind, bindl, binde, ...: the lists. `binds` is a config section, a set.
+      (builtins.filter (k: lib.hasPrefix "bind" k && builtins.isList s.${k}) (builtins.attrNames s));
+  macKeybindings = pkgs.runCommand "orca-mac-keybindings" {
+    nativeBuildInputs = [ pkgs.nodejs pkgs.asar pkgs.makeWrapper ];
+  } ''
+    asar extract ${appimageContents}/resources/app.asar app
+    mkdir -p $out/share $out/bin
+    node ${./nix/orca-mac-keybindings.js} app/out/shared \
+      ${pkgs.writeText "hyprland-chords.json" (builtins.toJSON hyprlandChords)} \
+      > $out/share/orca-mac-keybindings.json
+    # The merge runs Orca's conflict check on the merged file at activation,
+    # so the keybinding module (and its one sibling import) ships alongside.
+    mkdir -p $out/lib/shared
+    cp -r app/out/shared/keybindings.js app/out/shared/keybindings \
+      app/out/shared/tui-agent-display-names.js $out/lib/shared/
+    makeWrapper ${pkgs.nodejs}/bin/node $out/bin/orca-mac-keybindings \
+      --add-flags "${./nix/orca-mac-keybindings-merge.js} $out/lib/shared $out/share/orca-mac-keybindings.json"
+    # One real merge, so an Orca bump that moves an import or an export the
+    # merge uses fails here, not as a warning at every activation. The seed
+    # is a string (comma-list) value, so the shorthand parser runs too.
+    mkdir -p $TMPDIR/home/.orca
+    echo '{"version":1,"keybindings":{},"platforms":{"linux":{"zoom.reset":"Alt+0, Alt+Shift+0"}}}' \
+      > $TMPDIR/home/.orca/keybindings.json
+    HOME=$TMPDIR/home $out/bin/orca-mac-keybindings 2> merge.err
+    if [ -s merge.err ] \
+       || ! grep -q '"Cmd+W"' $TMPDIR/home/.orca/keybindings.json \
+       || ! grep -q '"Alt+0, Alt+Shift+0"' $TMPDIR/home/.orca/keybindings.json \
+       || [ ! -s $TMPDIR/home/.orca/keybindings.nix-owned.json ]; then
+      cat merge.err >&2; echo "orca: build-time merge did not apply the table" >&2; exit 1
+    fi
+  '';
+  # ~/.orca/keybindings.json is Orca's read-write state: its settings UI saves
+  # into the same platforms.linux section, by atomic rename, so a home.file
+  # symlink would be replaced on the first edit. So the generated keys are
+  # merged into whatever Orca last wrote, owning only what the last merge
+  # wrote (a sidecar records it), and a UI edit outranks them -- the rules
+  # are at the top of nix/orca-mac-keybindings-merge.js.
+  # tests/orca-mac-keybindings.sh.
 in
 {
   home.packages =
@@ -98,4 +158,9 @@ in
     # same reason parsec gets it.
       (config.lib.nixGL.wrap orca)
     ];
+
+  home.activation.orcaMacKeybindings = lib.mkIf (!isDarwin && isDesktop)
+    (lib.hm.dag.entryAfter [ "writeBoundary" ] ''
+      $DRY_RUN_CMD ${macKeybindings}/bin/orca-mac-keybindings
+    '');
 }

