              hl.exec_cmd("${pkgs.xorg.xrdb}/bin/xrdb -merge ${config.home.homeDirectory}/.Xresources")
              hl.exec_cmd("mako")
              hl.exec_cmd("hypr-fullscreen-inhibit")
              hl.exec_cmd("elephant")
            end'')
        ];
      }

